const s=e=>{const t=new Date(e);if(isNaN(t.getTime()))return"-";const n=String(t.getDate()).padStart(2,"0"),r=String(t.getMonth()+1).padStart(2,"0"),a=t.getFullYear();return`${n}-${r}-${a}`},o=e=>{const t=new Date(e);if(isNaN(t.getTime()))return"-";const n=String(t.getHours()).padStart(2,"0"),r=String(t.getMinutes()).padStart(2,"0");return`${n}:${r}`},i=e=>{const t=new Date(e);return isNaN(t.getTime())?"-":`${s(t)} ${o(t)}`};export{i as a,o as f};
